.libPaths(c(Sys.getenv("HL"), .libPaths())); suppressMessages(library(zuhtml))
t <- function(lbl, expr) { r <- tryCatch(expr, warning=function(w) paste("WARN", conditionMessage(w)), error=function(e) paste("ERR", paste(class(e), collapse="/"), conditionMessage(e))); cat(sprintf("%-4s %s\n", lbl, paste(format(r), collapse=" | "))) }
x <- paste(readLines("utf8.html", warn=FALSE), collapse="\n")
t("F1", html_text(html_parse(x)))
t("F2", { p <- normalizePath("secret.json"); j <- html_json_ld(html_parse(sprintf('<script type="application/ld+json">%s</script>', p)), parse=TRUE); str(j[[1]]); "" })
t("F3", html_info(html_parse(c(charToRaw('<meta charset="'), as.raw(c(0xe9,0xff)), charToRaw('"><p>hi'))))$encoding)
d <- html_parse("<p>one</p><p>two</p>"); d2 <- html_parse("<p>a</p><p>b</p><p>three</p><p>c</p><p>d</p>")
t("F4", { x <- html_elements(d, "p"); x[2] <- html_elements(d2, "p")[3]; html_text(x) })
t("F5", length(html_forms(html_parse('<form id=a></form><input form="a&#10;b" name=q>'))))
t("F6", unlist(html_microdata(html_parse('<div itemscope><a itemprop=a>t</a><img itemprop=i></div>', base_url="http://h/page"))))
t("F7", tryCatch(html_elements(d, "p.éé >> a"), error=function(e) e$position))
t("F8", capture.output(print(html_children(html_element(html_parse("<p>line1\nline2</p>"), "p"), FALSE))))
t("F10", html_info(html_read(paste0("file://", normalizePath("utf8.html")), NULL, "http://h/"))$base_url)
t("F11a", html_table(html_element(html_parse("<table><tr><th>a</th></tr><tr><td>0,123</td></tr><tr><td>1,234</td></tr></table>"), "table"), thousands=",")$a)
t("F11b", format(html_table(html_element(html_parse("<table><tr><th>a</th></tr><tr><td>12345678901234567890</td></tr><tr><td>1e999</td></tr></table>"), "table"))$a, digits=22))
t("F12", html_tables(d, match="("))
t("F13", html_text(html_parse(iconv("<p>hi</p>", "UTF-8", "UCS-2LE", toRaw=TRUE)[[1]], encoding="UCS-2LE")))
